<script setup>import {computed} from 'vue';import {useRoute} from 'vue-router';import {projects} from '../data.js';const route=useRoute();const project=computed(()=>projects.find(p=>p.id===route.query.id)||projects[0])</script><template><section class="project-detail"><img :src="project.cover" :alt="project.title"/><div class="project-copy"><span class="eyebrow">{{project.category}}  |  Selected project</span><h1>{{project.title}}</h1><p>{{project.description}}</p><RouterLink to="/contact" class="button">Inquire about a session</RouterLink></div></section><section class="section"><p class="notice">Project details and imagery are sample content for this frontend demo.</p><RouterLink to="/portfolio" class="text-link">Back to portfolio Back to portfolio</RouterLink></section></template>
